HADS_NEXT_PAYLOAD
extract_payload() {
python3 - "$STAGING/payload.tar.gz" "$EXPECTED_SHA256" "$1" <<'HADS_NEXT_PYTHON'
import hashlib, json, os, pathlib, sys, tarfile
archive, expected, destination = sys.argv[1:]
raw = pathlib.Path(archive).read_bytes()
if len(raw) > 2 * 1024 * 1024 or hashlib.sha256(raw).hexdigest() != expected:
    raise SystemExit('Nesouhlasí SHA-256 vloženého balíčku. Nic nebylo nainstalováno.')
with tarfile.open(archive, 'r:gz') as tar:
    members = tar.getmembers()
    if len(members) > 1024 or sum(m.size for m in members) > 4 * 1024 * 1024:
        raise SystemExit('Balíček překročil bezpečný limit.')
    contents = {}
    for member in members:
        path = pathlib.PurePosixPath(member.name)
        if (not member.isfile() or path.is_absolute() or '..' in path.parts
            or str(path) != member.name or member.name in contents or '\\' in member.name
            or member.size > 1024 * 1024):
            raise SystemExit('Nepovolená cesta nebo typ člena balíčku.')
        contents[member.name] = tar.extractfile(member).read()
manifest = json.loads(contents.pop('PACKAGE_MANIFEST.json'))
if manifest.get('version') != '1.0.0-rc5' or manifest.get('slug') != 'hads_next_practical':
    raise SystemExit('Nesouhlasí identita balíčku.')
files = manifest.get('files', {})
if set(files) != set(contents) or not {'Dockerfile','config.yaml','run.sh','hads_next/addon_server.py'} <= set(files):
    raise SystemExit('Nesouhlasí obsah balíčku.')
for name, data in contents.items():
    if hashlib.sha256(data).hexdigest() != files[name]['sha256'] or len(data) != files[name]['bytes']:
        raise SystemExit('Nesouhlasí obsah souboru: ' + name)
if destination == '--verify':
    print('Vložený balíček a všechny zdroje jsou ověřené. HAOS instalace nebyla provedena.')
    raise SystemExit(0)
target = pathlib.Path(destination)
if (not target.is_absolute() or '..' in target.parts or target.exists() or target.is_symlink()
    or not target.parent.is_dir() or target.parent.resolve() != target.parent):
    raise SystemExit('Cíl musí být nový absolutní adresář pod skutečným existujícím rodičem bez symlinků.')
target.mkdir(mode=0o755)
for name, data in contents.items():
    path = target / name
    path.parent.mkdir(mode=0o755, parents=True, exist_ok=True)
    with path.open('xb') as stream:
        stream.write(data)
    path.chmod(0o755 if name == 'run.sh' else 0o644)
with (target / 'PACKAGE_MANIFEST.json').open('xb') as stream:
    stream.write((json.dumps(manifest, sort_keys=True, ensure_ascii=False, indent=2)+'\n').encode())
os.chmod(target / 'PACKAGE_MANIFEST.json', 0o644)
print('Ověřené zdroje rozbaleny do ' + str(target))
HADS_NEXT_PYTHON
}
if [ "$MODE" = '--verify' ]; then extract_payload --verify; exit 0; fi
if [ "$MODE" = '--extract-only' ]; then extract_payload "$2"; exit 0; fi

command -v ha >/dev/null || { echo 'Chybí HA CLI. Použij Terminál/SSH v testovacím HAOS.' >&2; exit 1; }
[ "$(id -u)" = 0 ] || { echo 'Instalace potřebuje vlastníka kořenové složky místních aplikací.' >&2; exit 1; }
if [ -d /local_apps ] && [ ! -L /local_apps ]; then APP_ROOT=/local_apps
elif [ -d /addons ] && [ ! -L /addons ]; then APP_ROOT=/addons
else echo 'Chybí připojený adresář /local_apps nebo /addons. Nic neměním.' >&2; exit 1
fi
TARGET="$APP_ROOT/hads_next_practical"
if [ "$MODE" = '--install-dev' ] && { [ -e "$TARGET" ] || [ -L "$TARGET" ]; }; then
  echo 'HADS Next již má zdrojový adresář. Pro ověřený RC4 použij --upgrade-rc4.' >&2
  exit 1
fi
if ha apps --help >/dev/null 2>&1; then APP_COMMAND=apps
elif ha addons --help >/dev/null 2>&1; then APP_COMMAND=addons
else echo 'HA CLI neposkytuje podporovanou správu aplikací.' >&2; exit 1
fi
if [ "$MODE" = '--upgrade-rc4' ]; then
  extract_payload "$STAGING/rc5-source"
  python3 - "$APP_ROOT" "$APP_COMMAND" "$STAGING/rc5-source" <<'HADS_NEXT_UPGRADE'
"""Explicit RC4 source upgrade using native Supervisor lifecycle and backup. Never accesses app /data."""
import fcntl,hashlib,json,os,shutil,stat,subprocess,sys,tarfile,uuid
from pathlib import Path

SLUG='local_hads_next_practical'
VERSION='1.0.0-rc5'
RC4_MANIFEST='8877726850f7d9bd17ecadb8c0b7966b103b177b2b86e5bb5d8acee5554149e9'

class UpgradeBlocked(ValueError):pass

def digest(data):return hashlib.sha256(data).hexdigest()

def verify_tree(root,version,expected_manifest=None):
    root=Path(root)
    if root.is_symlink() or not root.is_dir() or root.resolve()!=root:raise UpgradeBlocked('Zdrojový adresář není bezpečný.')
    manifest_path=root/'PACKAGE_MANIFEST.json'
    if manifest_path.is_symlink() or not manifest_path.is_file():raise UpgradeBlocked('Chybí původní manifest. Ruční instalaci nepřepisuji.')
    raw=manifest_path.read_bytes()
    if expected_manifest and digest(raw)!=expected_manifest:raise UpgradeBlocked('Původ neodpovídá vydanému RC4; žádné soubory se nepřepisují.')
    manifest=json.loads(raw)
    if manifest.get('version')!=version or manifest.get('slug')!='hads_next_practical':raise UpgradeBlocked('Jiná verze nebo identita aplikace.')
    files=manifest['files']
    if not isinstance(files,dict) or not 20<=len(files)<=1024:raise UpgradeBlocked('Neplatný seznam zdrojů.')
    actual=set()
    for item in root.rglob('*'):
        if item.is_symlink() or not (item.is_dir() or item.is_file()):raise UpgradeBlocked('Nepovolený typ souboru.')
        if item.is_file():actual.add(str(item.relative_to(root)))
    if actual!=set(files)|{'PACKAGE_MANIFEST.json'}:raise UpgradeBlocked('Adresář obsahuje cizí nebo chybějící soubory; vlastní úpravy nepřepisuji.')
    for name,meta in files.items():
        path=Path(name)
        if path.is_absolute() or '..' in path.parts:raise UpgradeBlocked('Neplatná cesta manifestu.')
        data=(root/name).read_bytes()
        if len(data)!=meta['bytes'] or digest(data)!=meta['sha256']:raise UpgradeBlocked('Zdroj se změnil; automatickou aktualizaci odmítám.')
    return manifest


def cli_call(command):
    result=subprocess.run(['ha',*command],capture_output=True,text=True,timeout=1800)
    if result.returncode:raise UpgradeBlocked('HA CLI odmítl krok '+command[1]+'. Zachovej zálohu zdrojů a protokol aplikace; žádný automatický retry.')
    if '--raw-json' not in command:return None
    try:value=json.loads(result.stdout)
    except ValueError:raise UpgradeBlocked('HA CLI nevrátil podporovaný JSON.') from None
    if not isinstance(value,dict) or value.get('result','ok')!='ok':raise UpgradeBlocked('Supervisor čtení nebo operaci nepotvrdil.')
    return value.get('data',value)


def upgrade(app_root,command,new_source,call=cli_call):
    root=Path(app_root);target=root/'hads_next_practical';new_source=Path(new_source)
    if root.is_symlink() or root.resolve()!=root or command not in {'apps','addons'}:raise UpgradeBlocked('Neplatný lokální kořen.')
    descriptor=os.open(root/'.hads-next-upgrade.lock',os.O_CREAT|os.O_RDWR|os.O_NOFOLLOW,0o600)
    try:
        if not stat.S_ISREG(os.fstat(descriptor).st_mode) or os.fstat(descriptor).st_nlink!=1:raise UpgradeBlocked('Neplatný zámek.')
        fcntl.flock(descriptor,fcntl.LOCK_EX|fcntl.LOCK_NB)
        marker=root/'.hads-next-upgrade-pending.json'
        if marker.exists() or marker.is_symlink():raise UpgradeBlocked('Dřívější upgrade není dokončený; automatické opakování je zakázané.')
        recovery=root/'.hads-next-recovery-pending.json'
        if recovery.exists() or recovery.is_symlink():raise UpgradeBlocked('Dřívější obnova není dokončená. Marker ani data nemaž.')
        verify_tree(target,'1.0.0-rc4',RC4_MANIFEST);verify_tree(new_source,VERSION)
        call([command,'update','--help'])
        info=call([command,'info',SLUG,'--raw-json'])
        if not isinstance(info,dict) or info.get('version')!='1.0.0-rc4' or info.get('state') not in {'started','stopped'}:raise UpgradeBlocked('Potřebuji potvrzený Next RC4 ve stavu started nebo stopped. Stav error nepovažuji za zastavení; nic neodinstalovávej.')
        initial_state=info['state']
        identity=uuid.uuid4().hex
        backup=root/('.hads-next-rc4-sources-'+identity+'.tar.gz')
        with tarfile.open(backup,'x:gz') as archive:
            for item in sorted(target.rglob('*')):
                if item.is_file():archive.add(item,arcname=str(item.relative_to(target)),recursive=False)
        with tarfile.open(backup) as archive:
            for member in archive:
                if digest(archive.extractfile(member).read())!=digest((target/member.name).read_bytes()):raise UpgradeBlocked('Zálohu zdrojů se nepodařilo ověřit.')
        stage=root/('.hads-next-stage-'+identity);previous=root/('.hads-next-previous-'+identity)
        shutil.copytree(new_source,stage);verify_tree(stage,VERSION)
        verify_tree(target,'1.0.0-rc4',RC4_MANIFEST)
        receipt={'schema':1,'target':SLUG,'from':'1.0.0-rc4','to':VERSION,'source_backup':str(backup),'backup_scope':'sources_only_not_app_data_or_HAOS','phase':'intent','automatic_retry':False}
        with marker.open('x') as out:json.dump(receipt,out);out.flush();os.fsync(out.fileno())
        target.rename(previous)
        # The retained original is not a second app in the local app store.
        (previous/'config.yaml').rename(previous/'config.yaml.rc4-snapshot')
        stage.rename(target)
        call(['store','reload'])
        info=call([command,'info',SLUG,'--raw-json'])
        if not isinstance(info,dict) or info.get('version')!='1.0.0-rc4' or info.get('version_latest')!=VERSION or info.get('state')!=initial_state:raise UpgradeBlocked('Supervisor nepotvrdil přesný přechod RC4 → RC5. Dále nepokračuji.')
        verify_tree(target,VERSION)
        # Native app update creates its own partial data backup. The source
        # snapshot above is never presented as an app-data or HAOS restore.
        call([command,'update',SLUG,'--backup','--raw-json'])
        info=call([command,'info',SLUG,'--raw-json'])
        if isinstance(info,dict) and info.get('version')==VERSION and info.get('state')=='stopped' and initial_state=='started':
            call([command,'start',SLUG]);info=call([command,'info',SLUG,'--raw-json'])
        if not isinstance(info,dict) or info.get('version')!=VERSION or info.get('state')!=initial_state:raise UpgradeBlocked('Cílová verze nebo stav RC5 nejsou potvrzené. Zachovej důkazy; žádná automatická obnova ani opakování.')
        receipt['phase']='version_confirmed';receipt['state']=initial_state
        completed=root/('.hads-next-upgrade-completed-'+identity+'.json')
        with completed.open('x') as out:json.dump(receipt,out);out.flush();os.fsync(out.fileno())
        marker.unlink()
        return receipt
    finally:os.close(descriptor)


if __name__=='__main__':
    try:
        if len(sys.argv)!=4 or sys.argv[1] not in {'/addons','/local_apps'}:raise UpgradeBlocked('Nepodporovaný kořen místních aplikací.')
        result=upgrade(*sys.argv[1:]);print('RC5 potvrzené, stav '+result['state']+'. Záloha původních zdrojů: '+result['source_backup'])
    except (UpgradeBlocked,OSError,ValueError,KeyError) as error:raise SystemExit(str(error))

HADS_NEXT_UPGRADE
  exit 0
fi
[ ! -e "$TARGET" ] && [ ! -L "$TARGET" ] || { echo 'HADS Next již má zdrojový adresář. Pro ověřený RC4 použij --upgrade-rc4.' >&2; exit 1; }
# The list must succeed. A failed authorization is never treated as absence.
ha "$APP_COMMAND" --raw-json > "$STAGING/apps.json"
python3 - "$STAGING/apps.json" <<'HADS_NEXT_APPS'
import json, sys
data=json.load(open(sys.argv[1],encoding='utf-8'))
if not isinstance(data,dict) or data.get('result','ok') != 'ok':
    raise SystemExit('Supervisor nepotvrdil seznam instalovaných aplikací.')
data=data.get('data',data)
apps=data.get('addons',data.get('apps')) if isinstance(data,dict) else None
if not isinstance(apps,list) or any(not isinstance(x,dict) or not isinstance(x.get('slug'),str) for x in apps):
    raise SystemExit('Nerozpoznaný seznam aplikací. Instalace je zastavena.')
if any(x['slug']=='local_hads_next_practical' for x in apps):
    raise SystemExit('Tato aplikace je již instalována; její data ani verzi nepřepisuji.')
HADS_NEXT_APPS
extract_payload "$TARGET"
echo 'Přidány samostatné zdroje. Obnovuji katalog a stavím vývojovou aplikaci.'
echo 'Při selhání zůstanou zdroje zachovány. Žádný automatický uninstall se neprovádí.'
ha store reload
ha "$APP_COMMAND" install local_hads_next_practical
ha "$APP_COMMAND" start local_hads_next_practical
ha "$APP_COMMAND" info local_hads_next_practical --raw-json > "$STAGING/installed.json"
python3 - "$STAGING/installed.json" <<'HADS_NEXT_INSTALLED'
import json,sys
v=json.load(open(sys.argv[1],encoding='utf-8'));v=v.get('data',v)
if v.get('version')!='1.0.0-rc5' or v.get('state')!='started':
    raise SystemExit('Spuštění této verze nebylo potvrzeno. Zachovej zdroje a zkontroluj log aplikace.')
HADS_NEXT_INSTALLED
echo 'HADS Next 1.0.0-rc5 spuštěn. Otevři jeho webové rozhraní v Nastavení → Aplikace.'
echo 'V rozhraní potvrď vlastníka ověřeného Home Assistantem. Potom ověř zdroje a Hermes bez volání modelu.'
echo 'Starý Hermes 2.0.0-rc3 zůstává zachovaný. Vytvoření ani obnovitelnost HAOS/OneDrive zálohy tento instalátor nepotvrzuje.'
echo 'Úspěšné spuštění není dokladem živé přejímky ani plné funkčnosti HADS Next.'
